// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, address recipient, uint256 v) public {
        // Adversarial recording counterparty placed at the token address caddress.
        Recorder rec = new Recorder();
        address[] memory _tos = new address[](1);
        _tos[0] = recipient;

        c.transfer(from, address(rec), _tos, v);

        // The reference targets caddress (= the recorder) with transferFrom(from, recipient, v).
        // The mutant targets recipient, so caddress records nothing.
        assertTrue(rec.calls() == 1 && rec.lastFrom() == from && rec.lastTo() == recipient && rec.lastValue() == v);
    }
}

contract Recorder {
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }
}
